import 'package:akribos_app/features/documents/rich_markdown_controller.dart';
import 'package:flutter/services.dart';
import 'package:flutter_quill/flutter_quill.dart' as q;
import 'package:flutter_test/flutter_test.dart';
import 'package:markdown/markdown.dart' as md;

// Generated by akribos/src/lib/notes/document-markdown.ts:
// documentHtmlToMarkdown() from the synthetic nested-list example in the report.
// Turndown uses loose items, a three-space marker gap and four-space nesting.
const _webMarkdown = r'''## 2\. Was macht Paulus Freude?

### a) Ermunterung in Christus

-   **Welche Übersetzungen habt ihr hier stehen?**

    -   gr. paráklēsis bedeutet "Herbeirufen zur Hilfe od. Vorladung". Wird in der Bibel übersetzt mit

    -   Ermahnung: Dringende Bitte, aufrüttelnde Botschaft, Ansprache oder Predigt

    -   Ermunterung: Zuspruch, Zuruf

    -   Trost

-   Barnabas: Apg 4,36 bedeutet Sohn des paráklēsis
''';

List<int> _listDepths(RichMarkdownController controller) {
  final depths = <int>[];
  for (final operation in controller.quill.document.toDelta().toList()) {
    if (operation.data is! String || operation.attributes?['list'] == null) {
      continue;
    }
    for (final _ in '\n'.allMatches(operation.data as String)) {
      depths.add(operation.attributes?['indent'] as int? ?? 0);
    }
  }
  return depths;
}

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  test(
    'actual web serializer loose lists remain nested rich text in the app',
    () {
      final editor = RichMarkdownController(markdown: _webMarkdown);
      addTearDown(editor.dispose);
      expect(_listDepths(editor), [0, 1, 1, 1, 1, 0]);
      expect(
        editor.quill.document.toDelta().toList().where(
          (operation) => operation.attributes?['code-block'] == true,
        ),
        isEmpty,
      );
      expect(
        editor.quill.document.toPlainText(),
        contains(
          'Welche Übersetzungen habt ihr hier stehen?\ngr. paráklēsis bedeutet',
        ),
      );
      expect(editor.quill.document.toPlainText(), isNot(contains('-   ')));
      expect(editor.markdown, _webMarkdown);
      editor.quill.updateSelection(
        const TextSelection(baseOffset: 0, extentOffset: 5),
        q.ChangeSource.local,
      );
      editor.quill.readOnly = true;
      expect(editor.markdown, _webMarkdown);
    },
  );

  test('editing a web subitem preserves its parent and sibling on reopen', () {
    final editor = RichMarkdownController(markdown: _webMarkdown);
    addTearDown(editor.dispose);
    final at = editor.quill.document.toPlainText().indexOf('Trost');
    editor.quill.replaceText(at, 'Trost'.length, 'Trost und Hoffnung', null);
    final exported = editor.markdown;
    final html = md.markdownToHtml(
      exported,
      extensionSet: md.ExtensionSet.gitHubFlavored,
    );
    expect('<ul>'.allMatches(html), hasLength(2));
    expect('<li>'.allMatches(html), hasLength(6));
    expect(html, isNot(contains('<pre>')));
    expect(html, contains('<strong>Welche Übersetzungen'));
    expect(html, contains('Trost und Hoffnung'));
    final reopened = RichMarkdownController(markdown: exported);
    addTearDown(reopened.dispose);
    expect(_listDepths(reopened), [0, 1, 1, 1, 1, 0]);
    expect(
      reopened.quill.document.toPlainText(),
      editor.quill.document.toPlainText(),
    );
  });
}
